import sys

v = int(sys.stdin.read().split()[0])
INF = float('inf')
D = (1, 2, 5, 10, 20, 50, 100, 200, 500, 2000)
dp = [0] + [INF] * v
for x in range(1, v + 1):
    for d in D:
        if d <= x and dp[x - d] + 1 < dp[x]:
            dp[x] = dp[x - d] + 1
print(dp[v])

